function generateDiscovery() {
  // 分类维度配置 
  const categories = [
    {name: "全部作品", id: "0"},
    {name: "都市激情", id: "1"},
    {name: "武侠古典", id: "2"},
    {name: "腐小说", id: "3"},
    {name: "校园春色", id: "4"},
    {name: "家庭伦理", id: "5"},
    {name: "言情小说", id: "6"},
    {name: "凌虐调教",  id: "7"},
    {name: "肉文合集", id: "8"},
    {name: "玄幻其他", id: "9"},
  ];

  const statusTypes = [
    {name: "📌全部", id: "2"},
    {name: "📌连载", id: "0"}, 
    {name: "📌完本", id: "1"}
  ];

  const wordCountTypes = [
    {name: "全部", id: "0"},
    {name: "0-20万", id: "1"},
    {name: "20-50万", id: "2"},
    {name: "50-100万", id: "3"},
    {name: "100万+", id: "4"}
  ];

  let discovery = [];

  // 主分类导航 
  categories.forEach(cat => {
    discovery.push({
      title: cat.name,
      url: `/category/${cat.id}/{{page}}/2/0`,
      style: {"layout_flexBasisPercent": 0.95}
    });

    // 状态分类 
    statusTypes.forEach(status => {
      discovery.push({
        title: status.name,
        url: `/category/${cat.id}/{{page}}/${status.id}/0`,
        style: {"layout_flexBasisPercent": 0.45}
      });

      // 字数筛选 
      wordCountTypes.forEach(wc => {
        discovery.push({
          title: wc.name,
          url: `/category/${cat.id}/{{page}}/${status.id}/${wc.id}`,
          style: {"layout_flexBasisPercent": 0.45}
        });
      });
    });
  });

  return JSON.stringify(discovery);
}
generateDiscovery();

